{
  "incident": {
    "component": "mongodb",
    "category": "disk_pressure",
    "status": "firing",
    "summary": "MongoDB instance mongo-prod-03 is running low on disk space with an estimated 8 hours until exhaustion."
  },
  "assessment": {
    "urgency": "high",
    "rationale": "The computed Time-To-Exhaustion is 8.0 hours, which is less than the 12-hour threshold defined in the computed analysis."
  },
  "facts": [
    "used_pct is 92.0%",
    "filesystem_size_bytes is 536870912000.0",
    "filesystem_available_bytes is 42949672960.0",
    "growth_rate_bytes_per_hour is 5368709120.0",
    "replica_set_role is secondary",
    "label.alertname is MongoDBDiskSpaceLow",
    "label.instance is mongo-prod-03:9216",
    "label.severity is warning"
  ],
  "missing_context": [
    {
      "item": "user_impact",
      "why": "The impact on end-users or dependent services is unknown.",
      "how_to_check": "Check SLO dashboards for dependent services; check support tickets/status page."
    },
    {
      "item": "recent_changes",
      "why": "There is no context regarding recent deployments or configuration changes.",
      "how_to_check": "Check CI/CD history and change calendar for the last 24h."
    },
    {
      "item": "replication_lag_seconds",
      "why": "Replication lag is unknown, which is critical given the node is a secondary.",
      "how_to_check": "Run `rs.printSecondaryReplicationInfo()`."
    },
    {
      "item": "replica_set_healthy_members",
      "why": "The health and count of members in the replica set are unknown.",
      "how_to_check": "Run `rs.status()`."
    }
  ],
  "immediate_actions": [
    {
      "action": "Identify the noisy writer or high-volume process (e.g., batch job, migration) writing to the database.",
      "purpose": "Reduce the rate of disk consumption to buy time.",
      "conditions": "TTE is less than 12 hours.",
      "expected_effect": "Disk usage growth rate decreases or stabilizes.",
      "risks": "If the noisy writer is critical, throttling it could cause application errors or data processing delays. Rollback: Re-enable the process.",
      "requires_approval": false,
      "verify": "Monitor `growth_rate_bytes_per_hour` after action.",
      "rule_ids": [
        "global.harm.001"
      ]
    },
    {
      "action": "Check the disk usage of subdirectories within the MongoDB data path (`dbPath`) and log directories (`/var/log/mongodb`).",
      "purpose": "Find the source of the growth before attempting database-level cleanup.",
      "conditions": "Disk usage is high.",
      "expected_effect": "Pinpoint if the growth is due to logs, journals, or large collections.",
      "risks": "None, this is a read-only check. However, aggressive log rotation must be done carefully.",
      "requires_approval": false,
      "verify": "Examine output of `du -sh <dbPath_subdirs>`.",
      "rule_ids": [
        "mongo.storage.005"
      ]
    }
  ],
  "investigation_steps": [
    {
      "step": "Check the health and replication status of the entire replica set.",
      "hypothesis": "The disk pressure might be a symptom of a replication issue (e.g., a lagging secondary causing log buildup) or a primary failure.",
      "how_to_check": "Run `rs.status()` and `rs.printSecondaryReplicationInfo()`."
    },
    {
      "step": "Examine database statistics to identify the largest collections by storage size.",
      "hypothesis": "A few large collections are consuming the majority of space.",
      "how_to_check": "Run `db.stats()` and sort by storageSize; check `db.collection.stats()` for specific collections."
    },
    {
      "step": "Verify if any critical TTL indexes are missing or if log rotation is active.",
      "hypothesis": "Unmanaged data (like old logs or documents without TTL) is causing the growth.",
      "how_to_check": "Run `db.collection.getIndexes()` on high-growth collections; check system logs for log rotation activity."
    }
  ],
  "root_cause_hypotheses": [
    "A runaway process (e.g., a large data import or background job) is generating excessive writes.",
    "A specific collection has grown unexpectedly due to a change in application behavior (e.g., logging verbosity increase).",
    "Log files (e.g., MongoDB logs or OS logs) are not being rotated or are consuming excessive space."
  ],
  "dangerous_operations": [
    {
      "operation": "compact",
      "why_dangerous": "Compaction generates heavy I/O, which can exacerbate disk pressure and slow replication on a struggling node.",
      "rule_id": "mongo.storage.002"
    },
    {
      "operation": "drop collection/database",
      "why_dangerous": "This is irreversible without a verified backup and owner sign-off.",
      "rule_id": "mongo.storage.006"
    }
  ],
  "applied_expert_rules": [
    "global.triage.001",
    "global.harm.001",
    "mongo.storage.005"
  ],
  "incident_update": "🔥 HIGH: MongoDB disk space is at 92% (TTE ~8h). We are currently secondary. Immediate actions focus on finding the noisy writer and checking log/collection sizes. No destructive operations proposed yet. Next step: Check RS health and identify largest collections."
}
